-- Migration 007 — Fix: connections pour invitations externes
-- Pré-requis: migration-001 déjà appliquée
-- ══════════════════════════════════════════════════════════════
-- Problème: target_id était NOT NULL → impossiblee d'inviter un
--           email externe. Les colonnes target_email et
--           invitation_token n'existaient pas.
-- ══════════════════════════════════════════════════════════════

-- 1. Rendre target_id nullable (invitations externes sans compte)
ALTER TABLE public.connections
  ALTER COLUMN target_id DROP NOT NULL;

-- 2. Ajouter la colonne email cible pour invitations externes
ALTER TABLE public.connections
  ADD COLUMN IF NOT EXISTS target_email text;

-- 3. Ajouter le token d'invitation unique pour les liens externes
ALTER TABLE public.connections
  ADD COLUMN IF NOT EXISTS invitation_token text UNIQUE;

-- 4. Contrainte : soit target_id soit target_email doit être présent
ALTER TABLE public.connections
  DROP CONSTRAINT IF EXISTS connections_target_check;

ALTER TABLE public.connections
  ADD CONSTRAINT connections_target_check
    CHECK (target_id IS NOT NULL OR target_email IS NOT NULL);

-- 5. Index pour lookup rapide par token
CREATE INDEX IF NOT EXISTS idx_connections_invitation_token
  ON public.connections (invitation_token)
  WHERE invitation_token IS NOT NULL;

-- 6. Index pour lookup rapide par email cible
CREATE INDEX IF NOT EXISTS idx_connections_target_email
  ON public.connections (target_email)
  WHERE target_email IS NOT NULL;

-- 7. Policy SELECT : aussi visible via email si l'utilisateur s'inscrit ensuite
DROP POLICY IF EXISTS "Voir ses connexions" ON public.connections;
CREATE POLICY "Voir ses connexions" ON public.connections
  FOR SELECT USING (
    auth.uid() = requester_id
    OR auth.uid() = target_id
  );

SELECT 'Migration 007 terminée ✓' as status;
